<script setup lang="ts">
const api = useApi(), notice = useNotice(), route = useRoute()
const binders = ref<any[]>([]), loading = ref(true), open = ref(route.query.new === '1'), busy = ref(false)
const form = reactive({ title: '', description: '', columns: 3, rows: 3, page_count: 10, color: '#5546d8' })
const generatorOpen = ref(false)
const colors = ['#5546d8','#237b73','#d47544','#3467a5','#88456e','#303948']
async function load() { loading.value = true; try { binders.value = await api('/api/binders') } catch (e) { notice.show(errorMessage(e), 'error') } finally { loading.value = false } }
onMounted(load)
async function create() {
  busy.value = true
  try { const binder = await api('/api/binders', { method: 'POST', body: { ...form } }); await navigateTo('/binders/' + binder.id) }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
</script>
<template><header class="page-heading"><div><span class="eyebrow">A PLACE FOR EVERY CARD</span><h1>Your binders</h1><p>Collection, wishlist, or master set. Give each one its own space.</p></div><div class="button-row"><button class="button secondary" @click="generatorOpen = true">From set / series</button><button class="button primary" @click="open = true"><AppIcon name="plus" :size="18" />Blank binder</button></div></header><p v-if="loading" class="loading-panel">Loading binders…</p><div v-else-if="binders.length" class="binder-list full-list"><NuxtLink v-for="binder in binders" :key="binder.id" :to="'/binders/' + binder.id" class="binder-card"><div class="binder-cover" :style="{ '--binder-color': binder.color }"><div class="binder-rings"><i /><i /><i /></div><AppIcon name="binder" :size="42" /><span>{{ binder.title }}</span><small>{{ binder.columns }} × {{ binder.rows }} POCKET LAYOUT</small></div><div class="binder-card-info"><strong>{{ binder.title }}</strong><span>{{ binder.page_count }} pages · {{ binder.filled }} / {{ binder.columns * binder.rows * binder.page_count }} pockets</span><small v-if="binder.share_token" class="purple-text">Read-only sharing enabled</small></div></NuxtLink></div><section v-else class="empty-state tall"><div class="empty-icon"><AppIcon name="binder" :size="46" /></div><h2>Make room for a great collection.</h2><p>Start with a blank binder. Fill it with cards you own or cards you hope to find.</p><button class="button primary" @click="open = true"><AppIcon name="plus" :size="18" />Create your first binder</button></section><p class="data-note">Binders are layout plans, not physical-copy reservations. The same printing can appear in several binders without changing your owned quantities.</p><SeriesBinderBuilder :open="generatorOpen" @close="generatorOpen = false" @created="load" /><AppModal :open="open" title="Create a new binder" @close="open = false"><form class="form-stack" @submit.prevent="create"><label>Binder name<input v-model="form.title" required maxlength="100" placeholder="e.g. My first master set" /></label><label>Description<textarea v-model="form.description" maxlength="1000" placeholder="What makes this binder special?" /></label><div class="form-columns"><label>Columns<select v-model.number="form.columns"><option :value="2">2</option><option :value="3">3</option><option :value="4">4</option></select></label><label>Rows<select v-model.number="form.rows"><option :value="2">2</option><option :value="3">3</option><option :value="4">4</option></select></label><label>Pages<input v-model.number="form.page_count" required type="number" min="1" max="60" /></label></div><div><label>Cover colour</label><div class="color-options"><button v-for="color in colors" :key="color" type="button" :style="{ background: color }" :class="{ selected: form.color === color }" :aria-label="'Choose ' + color" @click="form.color = color"><AppIcon v-if="form.color === color" name="check" :size="16" /></button></div></div><p class="muted small">{{ form.columns * form.rows }} pockets per page · {{ form.columns * form.rows * form.page_count }} total pockets</p><button class="button primary full" :disabled="busy">{{ busy ? 'Creating…' : 'Create binder' }}<AppIcon name="arrow" :size="18" /></button></form></AppModal></template>
